messages.content:
[tool error]
{
  "ok": false,
  "name": "draw_arc",
  "error": {
    "type": "invalid_params",
    "message": "'center' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-001' or 'C-101'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "center": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "[x, y]"
        },
        "radius": {
          "type": "number",
          "exclusiveMinimum": 0
        },
        "start_angle_deg": {
          "type": "number",
          "description": "degrees CCW from +X"
        },
        "end_angle_deg": {
          "type": "number",
          "description": "arc runs CCW from start to end"
        }
      },
      "required": [
        "space",
        "center",
        "radius",
        "start_angle_deg",
        "end_angle_deg"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "center": [
        1600.0,
        1800.0
      ],
      "radius": 800.0,
      "start_angle_deg": -90.0,
      "end_angle_deg": -60.0
    }
  },
  "warnings": []
}
